// Generates src/web/styles/tokens.css from design/design-system/tokens.json (the design system's source of truth).
// Same shape as design/tools/proto.mjs: dark first, light under prefers-color-scheme and [data-theme].
// Generated file — never edit tokens.css by hand; run `pnpm --filter @bowerbird/plugin-sdk gen:tokens`.
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
const here = path.dirname(fileURLToPath(import.meta.url))
const repo = path.resolve(here, '../../..')
const t = JSON.parse(fs.readFileSync(path.join(repo, 'design/design-system/tokens.json'), 'utf8'))
const themed = t.color.tokens.concat(t.shadow.tokens)
const block = th => themed.map(k => `  --${k.name}: ${typeof k.value === 'string' ? k.value : k.value[th]};`).join('\n')
let css = `/* Bowerbird design tokens — GENERATED by packages/plugin-sdk/scripts/gen-tokens.mjs from design/design-system/tokens.json. Do not edit. */\n:root {\n${block('dark')}\n`
for (const fam of Object.keys(t)) {
  if (['name', 'version', 'color', 'type', 'shadow'].includes(fam)) continue
  for (const k of t[fam].tokens) css += `  --${k.name}: ${k.value};\n`
}
for (const [k, v] of Object.entries(t.type.families)) css += `  --font-${k}: ${v};\n`
css += `  color-scheme: dark;\n}\n@media (prefers-color-scheme: light) {\n  :root:not([data-theme="dark"]) {\n${block('light').replace(/^/gm, '  ')}\n    color-scheme: light;\n  }\n}\n:root[data-theme="light"] {\n${block('light')}\n  color-scheme: light;\n}\n:root[data-theme="dark"] {\n${block('dark')}\n  color-scheme: dark;\n}\n`
css += `/* Type styles */\n`
for (const g of t.type.groups) for (const s of g.styles) css += `@utility ${s.name} { font-family: var(--font-${s.family ?? g.family}); font-size: ${s.fontSize}; line-height: ${s.lineHeight}; font-weight: ${s.fontWeight}; letter-spacing: ${s.letterSpacing ?? 0}; }\n`
fs.writeFileSync(path.join(here, '../src/web/styles/tokens.css'), css)
console.log('tokens.css written')
